return $input.all().map(item => {
  const rawTitle = item.json.title || '';
  const rawBody = item.json.body || '';

  // ==========================================
  // 1. 제목 정제 (연합뉴스 노이즈 완벽 차단)
  // ==========================================
  let title_clean = Array.isArray(rawTitle) ? rawTitle[0] : String(rawTitle);
  title_clean = title_clean.replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();

  // [핵심 해결 1] "|" 파이프 기호가 있으면 그 앞부분(순수 제목)만 싹둑 자르기
  // 보통 <title> 태그에 "기사제목 | 연합뉴스" 형태로 들어오기 때문에 여기서 중복이 깔끔하게 잘립니다.
  if (title_clean.includes('|')) {
      title_clean = title_clean.split('|')[0];
  }

  // [핵심 해결 2] 꼬리표처럼 붙는 연합뉴스/포털 메뉴 글귀 강제 삭제
  title_clean = title_clean
      .replace(/(핫뉴스|에디터스 픽|Editor's Picks|오래 머문 뉴스|랭킹뉴스|실시간 트렌드|이 시각 추천뉴스|서비스 바로가기).*$/gi, '')
      .replace(/\[.*?\]/g, '')
      .replace(/[◇▲▶■●◆※]/g, '')
      .trim();

  // 반으로 쪼개서 중복되는 기괴한 제목 2차 방어
  let halfLen = Math.floor(title_clean.length / 2);
  if (title_clean.length > 10 && title_clean.substring(0, halfLen) === title_clean.substring(halfLen, halfLen * 2)) {
      title_clean = title_clean.substring(0, halfLen);
  }

  // ==========================================
  // 2. 본문 텍스트 확보 (일반 HTML vs JTBC 방어)
  // ==========================================
  let rawBodyData = rawBody;
  if (!rawBodyData || rawBodyData.length === 0) {
      const rawData = item.json.data || '';
      const match = String(rawData).match(/"articleInnerTextContent":"([\s\S]*?)(?:","articleSummary|","articleLike)/);
      if (match) {
          rawBodyData = match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"');
      }
  }

  let content_clean = Array.isArray(rawBodyData) ? rawBodyData.join('\n') : String(rawBodyData);

  // ==========================================
  // 3. 구조화 및 HTML 찌꺼기 제거
  // ==========================================
  content_clean = content_clean.replace(/<(script|style|audio|video|iframe)[^>]*>[\s\S]*?<\/\1>/gi, '');
  content_clean = content_clean.replace(/<\/?(br|p|div|article|section|li|h[1-6])[^>]*>/gi, '\n');
  content_clean = content_clean.replace(/<[^>]+>/g, '');
  content_clean = content_clean.replace(/\b(loading|decoding|data-[a-z]+|src|style|alt|class|id)=['"][^'"]*['"]/gi, '');
  content_clean = content_clean.replace(/&nbsp;/gi, ' ').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>');

  // ==========================================
  // 4. 언론사별 정규식 및 하드코딩 노이즈 필터 통합
  // ==========================================
  content_clean = content_clean
    .replace(/\[.*?\]/g, '')
    .replace(/\([가-힣\s]+=[가-힣\s가-힣a-zA-Z0-9]+\)/g, '')
    .replace(/【?광고】?|AD(?=\s|$)|ADVERTISEMENT/g, '')
    .replace(/▲[^.]*(\s{2,}|\n)/g, '')
    .replace(/[가-힣]{2,4}\s*(기자|특파원|편집자|논설위원)\s*=\s*/g, '')
    .replace(/[가-힣]{2,4}\s*기자\s*[\w.]+@[\w.]+/g, '')
    .replace(/[\w.]+@[\w.]+\.[a-z]+/g, '')
    .replace(/[가-힣]+\s*기자$/g, '')
    .replace(/ⓒ.*?금지/g, '')
    .replace(/무단\s*전재.*?금지/g, '')
    .replace(/저작권자.*?금지/g, '')
    .replace(/[◇▲▶■●◆※]/g, '')
    .replace(/글자크기 설정 파란원을 좌우로 움직이시면 글자크기가 변경 됩니다.*?\(예시\)/g, '')
    .replace(/가장 빠른 뉴스가 있고 다양한 정보, 쌍방향 소통이 숨쉬는 다음뉴스를 만나보세요.*?입체적으로 전달하고 있습니다\./g, '')
    .replace(/실시간 트렌드 데이터는 안정화 기간 중 베타\(Beta\) 서비스로 운영하며.*?제한적으로 제공합니다\./g, '')
    .replace(/JTBC에서 직접 확인하세요\./g, '')
    .replace(/해당 언론사로 이동합니다\./g, '');

  // ==========================================
  // 5. 문장별 정밀 필터링 및 중복 제거
  // ==========================================
  let lines = content_clean.split('\n');
  let finalLines = [];

  for (let line of lines) {
    let trimmed = line.replace(/\s+/g, ' ').trim();

    if (trimmed.length <= 15) continue;

    if (
        trimmed.includes('기사를 읽어드립니다') || 
        trimmed.includes('기사 읽어주기') || 
        trimmed.includes('audio element') ||
        trimmed.includes('video 태그를 지원하지') ||
        trimmed.includes('카카오톡') ||
        trimmed.includes('자료사진') ||
        trimmed.includes('송고') ||
        trimmed.includes('Copyright') ||
        trimmed.includes('All rights reserved') ||
        // [핵심 해결 3] 연합뉴스 AI 요약 및 하단 배너 방어
        trimmed.includes('세 줄 요약') ||
        trimmed.includes('전체 내용을 이해하기 위해') ||
        trimmed.includes('맞춤 추천 뉴스를 제공합니다')
    ) continue;

    let lastChar = trimmed.slice(-1);
    if (!['.', '”', '"', '\'', ')', ']', '?', '>'].includes(lastChar)) {
        if (trimmed.length < 50) continue; 
    }

    finalLines.push(trimmed);
  }

  let uniqueLines = [...new Set(finalLines)];
  let finalContent = uniqueLines.join(' ').slice(0, 21000).trim();

  return { json: { title: title_clean, content: finalContent } };
});

