return $input.all().map(item => {
  // 1. 제미나이가 뱉어낸 텍스트를 가져옵니다.
  let rawText = item.json.text || "";

  // 2. 앞뒤에 붙은 마크다운 포장지(```json, ```)를 싹 지워버립니다.
  let cleanText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();

  // 3. 텍스트를 진짜 JSON '데이터'로 변환합니다.
  let parsedData = JSON.parse(cleanText);

  // 4. 변환된 데이터를 다음 노드로 넘겨줍니다.
  return { json: parsedData };
});

return $input.all().map(item => {
  // n8n이 감싸는 구조 디버깅용으로 전체 출력
  const raw = item.json;

  // 가능한 모든 경우 처리
  let predict;
  if (Array.isArray(raw)) {
    predict = raw[0];
  } else if (Array.isArray(raw.data)) {
    predict = raw.data[0];
  } else if (raw.predicted_class !== undefined) {
    predict = raw;
  } else {
    // 어디 숨었는지 찾기
    const keys = Object.keys(raw);
    predict = raw[keys[0]];
    if (Array.isArray(predict)) predict = predict[0];
  }

  return {
    json: {
      title: $('Json 파싱').first().json.title,
      content: $('Json 파싱').first().json.content,
      predicted_class: predict?.predicted_class ?? -1,
      confidence: predict?.confidence ?? 0
    }
  };
});
